<script setup lang="ts">
import { ui } from "../ui"
import DateTime from '../components/DateTime.vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowPathIcon } from '@heroicons/vue/24/outline'
import { bootstrap } from '../composables/api'
import ErrorListFilters from '../components/ErrorListFilters.vue'
import PageHeading from '../components/PageHeading.vue'
import ErrorsTable from '../components/ErrorsTable.vue'
import InvestigationFilters from '../components/InvestigationFilters.vue'
import { useInvestigation,queryString } from '../composables/investigation'
import type { InboxResult } from '../types'
const route=useRoute(),router=useRouter(),{data,loading,error,reload}=useInvestigation<InboxResult>(()=>'/issues?'+queryString(route.query))
function page(n:number){router.replace({query:{...route.query,page:String(n)}})}
</script>
<template><PageHeading :class="ui('$all', '$PageHeading')" title="Errors" subtitle="Investigate and triage captured exceptions"><InvestigationFilters :class="ui('$all', '$InvestigationFilters')" :environments="data?.environments" hide-test-toggle/><button :class="ui('$all', '$button', 'button icon-button')" aria-label="Refresh errors" :disabled="loading" @click="reload"><ArrowPathIcon :class="ui('$all', '$svg')"/></button></PageHeading><nav :class="ui('$all', '$nav', 'built-in-views')" aria-label="Built-in error views"><RouterLink v-for="status in ['unresolved','resolved','ignored','snoozed','all']" :key="status" :class="ui('$all', '$a', ({selected:(route.query.status??'unresolved')===status}))" :aria-current="(route.query.status??'unresolved')===status?'page':'false'" :to="{query:{...route.query,status,page:undefined}}">{{ status === 'all' ? 'All' : status }}</RouterLink><RouterLink :class="ui('$all', '$a')" v-if="bootstrap?.features.assignments" :to="{query:{...route.query,status:'unresolved',assignee:'me',view:undefined,page:undefined}}">Assigned to me</RouterLink></nav><ErrorListFilters :class="ui('$all', '$ErrorListFilters')" :allowed-tags="data?.allowed_tags"/><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert">{{ error }}<button :class="ui('$all', '$button', 'button')" @click="reload">Try again</button><RouterLink to="/errors" :class="ui('$all', '$a', 'text-link')">Clear filters</RouterLink></div><p v-if="loading" role="status" :class="ui('$all', '$p', 'loading-message')">Loading errors…</p><template v-if="data"><ErrorsTable :class="ui('$all', '$ErrorsTable')" :items="data.items" :range="data.window.range" focused/><div :class="ui('$all', '$div', 'pagination error-list-pagination')"><span :class="ui('$all', '$span')">{{ data.total }} {{data.total==='1'?'error':'errors'}} · page {{ data.page }} of {{ data.last_page }}</span><button :class="ui('$all', '$button', 'button')" :disabled="data.page<=1" @click="page(data.page-1)">Previous</button><button :class="ui('$all', '$button', 'button')" :disabled="data.page>=data.last_page" @click="page(data.page+1)">Next</button><RouterLink v-if="!data.items.length" to="/errors" :class="ui('$all', '$a', 'text-link')">Clear filters</RouterLink></div><p :class="ui('$all', '$p', 'data-caption error-list-caption')">Data as of <DateTime :class="ui('$all', '$DateTime')" :value="data.window.as_of"/><br :class="ui('$all', '$br')">{{ data.coverage }}</p></template></template>
